  23 class ResumeDriver
  24 {
  25 public:
  26   // data0/data1/abstractcs/command are defined once in abstract_command.hpp;
  27   // dmcontrol/dmstatus are run-control registers specific to this driver.
  28   static constexpr uint8_t kData0      = kDmiData0;
  29   static constexpr uint8_t kData1      = kDmiData1;
  30   static constexpr uint8_t kDmcontrol  = 0x10;
  31   static constexpr uint8_t kDmstatus   = 0x11;
  32   static constexpr uint8_t kAbstractcs = kDmiAbstractcs;
  33   static constexpr uint8_t kCommand    = kDmiCommand;
  34 
  35   static constexpr uint16_t kCsrDpc      = 0x7B1;
  36   static constexpr uint16_t kCsrFcsr     = 0x003;
  37   static constexpr uint16_t kCsrMstatus  = 0x300;
  38   static constexpr uint16_t kCsrMie      = 0x304;
  39   static constexpr uint16_t kCsrMtvec    = 0x305;
  40   static constexpr uint16_t kCsrMscratch = 0x340;
  41   static constexpr uint16_t kCsrMepc     = 0x341;
  42   static constexpr uint16_t kCsrMcause   = 0x342;
  43   static constexpr uint16_t kCsrMtval    = 0x343;
  44   static constexpr uint16_t kCsrMip      = 0x344;
  45   static constexpr uint16_t kCsrMcycle   = 0xB00;
  46   static constexpr uint16_t kCsrMinstret = 0xB02;
  47   // Andes machine setup CSRs crt0 writes at boot (see hybrid_state_v1):
  48   // mcache_ctl enables the L1 I/D caches, mmisc_ctl holds misc machine config.
  49   static constexpr uint16_t kCsrMcacheCtl = 0x7CA;
  50   static constexpr uint16_t kCsrMmiscCtl  = 0x7D0;
  51 
  52   static constexpr uint32_t kDmcontrolDmactive  = 1u << 0;
  53   static constexpr uint32_t kDmcontrolResumereq = 1u << 30;
  54   static constexpr uint32_t kDmcontrolHaltreq   = 1u << 31;
  55 
  56   static constexpr uint32_t kDmstatusAllhalted    = 1u << 9;
  57   static constexpr uint32_t kDmstatusAllresumeack = 1u << 17;
  58 
  59   static constexpr uint32_t kAbstractcsBusy       = hybrid::kAbstractcsBusy;
  60   static constexpr uint32_t kAbstractcsCmderrMask = hybrid::kAbstractcsCmderrMask;
  61 
  62   // mstatus extension-state fields: FS (bits 14:13), VS (bits 10:9).
  63   // "Initial" (01) is the minimal enable the abstract FPR / V writes require.
  64   static constexpr uint64_t kMstatusFsMask    = 0x6000ULL;
  65   static constexpr uint64_t kMstatusFsInitial = 0x2000ULL;
  66   static constexpr uint64_t kMstatusVsMask    = 0x600ULL;
  67   static constexpr uint64_t kMstatusVsInitial = 0x200ULL;
  68 
  69   static constexpr unsigned kPollIterations = kDmiPollIterations;
  70 
  71   explicit ResumeDriver(DmiBus& bus) : bus_{bus} {}
  72 
  73   void resume(const hybrid_state_v1& state)
  74   {
  75     if (state.magic != HYBRID_STATE_MAGIC)
  76       throw std::runtime_error("ResumeDriver::resume: bad magic");
  77     if (state.version != HYBRID_STATE_VERSION)
  78       throw std::runtime_error("ResumeDriver::resume: unsupported version");
  79     // L6: only U(0)/S(1)/M(3) fit dcsr.prv; 2 is the reserved encoding.
  80     if (state.priv == 2 || state.priv > 3)
  81       throw std::runtime_error("ResumeDriver::resume: invalid privilege");
  82 
  83     // dmactive must transition 0->1 in its own write before any other
  84     // DMCONTROL bit is honored (RISC-V Debug Spec).
  85     bus_.write(kDmcontrol, kDmcontrolDmactive);
  86     request_halt();
  87     poll_until_set(bus_, kDmstatus, kDmstatusAllhalted, "ResumeDriver halt");
  88 
  89     // mstatus: enable FS / VS so the following FPR / V abstract writes are
  90     // accepted (FS or VS == Off disables the extension and the hart NACKs
  91     // the writes). The drained state.mstatus may legitimately carry FS or
  92     // VS at Off (e.g. an OS context-switched the regs away before the
  93     // trigger fired) -- gating the write on the drained field skips the
  94     // enable and silently NACKs every subsequent FPR / V-CSR write. Always
  95     // write mstatus when either extension is in scope; force-OR Initial
  96     // when the drained field is Off. This enable is local to the vsim
  97     // phase; the state.mstatus written to the handoff file is left
  98     // unmodified.
  99     if (state.flags & (HYBRID_FLAG_FP | HYBRID_FLAG_V)) {
 100       uint64_t enable_mstatus = state.mstatus;
 101       if ((state.flags & HYBRID_FLAG_FP) && (enable_mstatus & kMstatusFsMask) == 0)
 102         enable_mstatus |= kMstatusFsInitial;  // FS = Initial
 103       if ((state.flags & HYBRID_FLAG_V)  && (enable_mstatus & kMstatusVsMask) == 0)
 104         enable_mstatus |= kMstatusVsInitial;  // VS = Initial
 105       write_csr_abstract_or_pb(kCsrMstatus, enable_mstatus);
 106     }
 107 
 108     // FPR restore (requires mstatus.FS enabled above): one abstract register
 109     // write per f-reg. Abstract-only by design, like every non-V register
 110     // block -- the Program Buffer is reserved for state the abstract command
 111     // space cannot reach (the V regfile, vtype/vl, L2C MMIO).
 112     if (state.flags & HYBRID_FLAG_FP) {
 113       for (uint16_t i = 0; i < 32; ++i)
 114         write_64bit_register(regno_fpr(i), state.fpr[i]);
 115       // L20: fcsr (frm + sticky fflags). Same FS gate as the FPRs; PB
 116       // fallback scratch x5 is overwritten by the GPR loop below.
 117       write_csr_abstract_or_pb(kCsrFcsr, state.fcsr);
 118     }
 119 
 120     // GPRs x1..x31 + DPC: one abstract register write each (DATA0/DATA1 +
 121     // Access-Register COMMAND), abstract-only by design. x0 is hardwired zero
 122     // and is skipped. M-mode CSRs, PMP and V land in later commits; M-mode
 123     // CSRs/PMP are pass-through-merged at drain time, never programmed through
 124     // a DM abstract command here.
 125     for (uint16_t i = 1; i < 32; ++i)
 126       write_64bit_register(regno_gpr(i), state.gpr[i]);
 127     write_64bit_register(regno_csr(kCsrDpc), state.pc);
 128 
 129     write_csr_tolerant(kCsrMtvec, state.mtvec);
 130 
 131     // L23: mscratch is the M-mode software scratch CSR -- a pure read/write
 132     // register with no hardware side effects, legal to use inside a trap-free
 133     // ROI. Restore it so a value stashed before the handoff survives into the
 134     // vsim phase.
 135     write_csr_tolerant(kCsrMscratch, state.mscratch);
 136 
 137     // L24: the writable M-mode trap/interrupt CSRs. In the trap-free,
 138     // interrupt-free ROI envelope these are ordinary read/write registers, so a
 139     // value stashed before the handoff must survive into the vsim phase (same
 140     // round-trip as mscratch). Tolerant writes: a WARL / read-only field (mip's
 141     // hardware-driven pending bits, or mtval on a core that hardwires it)
 142     // mirrors as a no-op. medeleg/mideleg/satp stay unrestored -- they are
 143     // S-mode CSRs the M-only default engine does not implement (L3/L4).
 144     write_csr_tolerant(kCsrMepc,   state.mepc);
 145     write_csr_tolerant(kCsrMcause, state.mcause);
 146     write_csr_tolerant(kCsrMtval,  state.mtval);
 147     write_csr_tolerant(kCsrMie,    state.mie);
 148     write_csr_tolerant(kCsrMip,    state.mip);
 149 
 150     // Andes cache fix: restore the machine setup CSRs crt0 wrote at boot. The
 151     // functional engine ran crt0 (where `csrw mcache_ctl` enables the L1 I/D
 152     // caches) but has no cache model, so without this the cycle engine resumes
 153     // at the ROI with caches at their reset default -- DISABLED -- and the
 154     // whole measured window runs uncached, inflating it severalfold. Tolerant
 155     // writes: an engine without these custom CSRs (e.g. non-Andes) mirrors the
 156     // write as a no-op, and a drained 0 (caches were off) restores the reset
 157     // state, so this is always safe to issue.
 158     write_csr_tolerant(kCsrMcacheCtl, state.mcache_ctl);
 159     write_csr_tolerant(kCsrMmiscCtl,  state.mmisc_ctl);
 160 
 161     // F-T2.4: restore mcycle/minstret so the vsim phase continues counting
 162     // from QEMU1's drain value. Without this, vsim's local counter starts
 163     // at zero, so the drained mcycle delta (vsim minus QEMU 1) would no
 164     // longer measure the ROI. PB fallback uses x5 as scratch; safe to
 165     // overwrite here as the GPR loop already ran.
 166     write_csr_abstract_or_pb(kCsrMcycle,   state.mcycle);
 167     write_csr_abstract_or_pb(kCsrMinstret, state.minstret);
 168 
 169     clear_cmderr_if_set();
 170     request_resume();
 171     poll_until_set(bus_, kDmstatus, kDmstatusAllresumeack,
 172                    "ResumeDriver resume");
 173   }
 174 
 175 private:
 176   void request_halt()
 177   {
 178     bus_.write(kDmcontrol, kDmcontrolDmactive | kDmcontrolHaltreq);
 179   }
 180 
 181   void request_resume()
 182   {
 183     bus_.write(kDmcontrol, kDmcontrolDmactive | kDmcontrolResumereq);
 184   }
 185 
 186   void write_64bit_register(uint16_t regno, uint64_t value)
 187   {
 188     write_register_abstract(bus_, regno, value);
 189   }
 190 
 191   // Abstract-first CSR write with Program Buffer fallback.
 192   // Tries an abstract register write; if the DM signals cmderr, clears it,
 193   // stages the value in scratch_gpr via abstract GPR write, then executes a
 194   // one-instruction PB (`csrrw x0, csr, scratch_gpr`).  scratch_gpr defaults
 195   // to x5 (t0) which the GPR restore loop overwrites later.
 196   void write_csr_abstract_or_pb(uint16_t csr, uint64_t value,
 197                                  uint8_t scratch_gpr = 5)
 198   {
 199     write_64bit_register(regno_csr(csr), value);
 200     if ((bus_.read(kAbstractcs) & kAbstractcsCmderrMask) == 0u) return;
 201     bus_.write(kAbstractcs, kAbstractcsCmderrMask);  // W1C: clear sticky error
 202     write_64bit_register(regno_gpr(scratch_gpr), value);
 203     const std::array<uint32_t, 1> pb = { encode_csrrw(0, csr, scratch_gpr) };
 204     exec_progbuf(bus_, std::span<const uint32_t>{pb});
 205   }
 206 
 207   // Write a CSR-addressable register and clear any cmderr the DM raised.
 208   // Used for CSRs whose abstract-access support may be implementation
 209   // dependent; a missing CSR mirrors as a no-op rather than blocking the
 210   // remaining writes.
 211   void write_csr_tolerant(uint16_t csr, uint64_t value)
 212   {
 213     write_64bit_register(regno_csr(csr), value);
 214     clear_cmderr_if_set();
 215   }
 216 
 217   // abstractcs.cmderr is sticky per the Debug Spec - a subsequent command
 218   // is rejected until the bits are W1C-cleared. We tolerate per-register
 219   // failures (e.g. unimplemented FPR/CSR Abstract access) by clearing the
 220   // error before resuming so the hart isn't left in a stuck state.
 221   // B17: record the last observed non-zero cmderr and a clear count so a
 222   // partially-broken restore is observable via the public accessors
 223   // instead of silently swallowed.
 224   void clear_cmderr_if_set()
 225   {
 226     const auto status = bus_.read(kAbstractcs);
 227     const auto code = (status & kAbstractcsCmderrMask) >> 8;
 228     if (code != 0u) {
 229       last_observed_cmderr_ = code;
 230       ++cmderr_clear_count_;
 231       bus_.write(kAbstractcs, kAbstractcsCmderrMask);
 232     }
 233   }
 234 
 235   DmiBus& bus_;
 236   uint32_t last_observed_cmderr_ = 0;
 237   uint64_t cmderr_clear_count_   = 0;
 238 
 239 public:
 240   // B17: diagnostic side channel. Non-zero last_observed_cmderr() means
 241   // at least one abstract write tripped a sticky cmderr the restore
 242   // tolerated by clearing. cmderr_clear_count() is the total number of
 243   // such clears across all calls into clear_cmderr_if_set() this run.
 244   auto last_observed_cmderr() const -> uint32_t { return last_observed_cmderr_; }
 245   auto cmderr_clear_count() const -> uint64_t   { return cmderr_clear_count_; }
 246 };
 247 
 248 // Read a 64-bit hart register (GPR / FPR / CSR by abstract regno) over DMI
 249 // via an Abstract Command. Halts-and-reads contract: caller must have the
 250 // hart in the halted state. Shared with StateDrain (drain at exit). If
 251 // abstractcs.cmderr goes sticky after the command, the helper clears it and
 252 // reports nullopt rather than blocking the caller -- a missing CSR mirrors as
 253 // absent instead of corrupting the adjacent field.
 254 inline auto read_register_64_checked(DmiBus& bus, uint16_t regno,
 255                                      const char* poll_label
 256                                        = "read_register_64")
 257   -> std::optional<uint64_t>
 258 {
 259   using RD = ResumeDriver;
 260   bus.write(RD::kCommand,
 261             access_register_command(regno, AarSize::Bits64, /*write=*/false));
 262   poll_until_clear(bus, RD::kAbstractcs, RD::kAbstractcsBusy, poll_label);
 263   const auto status = bus.read(RD::kAbstractcs);
 264   if ((status & RD::kAbstractcsCmderrMask) != 0u) {
 265     bus.write(RD::kAbstractcs, RD::kAbstractcsCmderrMask);
 266     return std::nullopt;
 267   }
 268   const uint64_t lo = bus.read(RD::kData0);
 269   const uint64_t hi = bus.read(RD::kData1);
 270   return lo | (hi << 32);
 271 }
 272 
 273 inline auto read_register_64(DmiBus& bus, uint16_t regno,
 274                              const char* poll_label = "read_register_64")
 275   -> uint64_t
 276 {
 277   return read_register_64_checked(bus, regno, poll_label).value_or(0u);
 278 }
 279 
 280 }  // namespace hybrid

