164	 162     // write mstatus when either extension is in scope; force-OR Initial
165	 163     // when the drained field is Off. This enable is local to the vsim
166	 164     // phase; the state.mstatus written to the handoff file is left
167	 165     // unmodified.
168	 166     if (state.flags & (HYBRID_FLAG_FP | HYBRID_FLAG_V)) {
169	 167       uint64_t enable_mstatus = state.mstatus;
170	 168       if ((state.flags & HYBRID_FLAG_FP) && (enable_mstatus & kMstatusFsMask) == 0)
171	 169         enable_mstatus |= kMstatusFsInitial;  // FS = Initial
172	 170       if ((state.flags & HYBRID_FLAG_V)  && (enable_mstatus & kMstatusVsMask) == 0)
173	 171         enable_mstatus |= kMstatusVsInitial;  // VS = Initial
174	 172       write_csr_abstract_or_pb(kCsrMstatus, enable_mstatus);
175	 173     }
176	 174 
177	 175     // FPR restore (requires mstatus.FS enabled above): one abstract register
178	 176     // write per f-reg. Abstract-only by design, like every non-V register
179	 177     // block -- the Program Buffer is reserved for state the abstract command
180	 178     // space cannot reach (the V regfile, vtype/vl, L2C MMIO).
181	 179     if (state.flags & HYBRID_FLAG_FP) {
182	 180       // LG2: elide the whole FPR block when every f-reg already holds the
183	 181       // engine's reset value -- the reload would rewrite what is there.
184	 182       const bool fpr_equal = has_baseline_
185	 183         && std::memcmp(state.fpr, baseline_.fpr, sizeof state.fpr) == 0;
186	 184       if (fpr_equal) {
187	 185         baseline_skip_count_ += 32;
188	 186       } else {
189	 187         for (uint16_t i = 0; i < 32; ++i)
190	 188           write_64bit_register(regno_fpr(i), state.fpr[i]);
191	 189       }
192	 190       // L20: fcsr (frm + sticky fflags). Same FS gate as the FPRs; PB
193	 191       // fallback scratch x5 is overwritten by the GPR loop below.
194	 192       if (!baseline_skips(state.fcsr, baseline_.fcsr))
195	 193         write_csr_abstract_or_pb(kCsrFcsr, state.fcsr);
196	 194     }
197	 195 
198	 196     // Tier-A V CSR restore (before GPRs: PB fallback uses x5 as scratch;
199	 197     // the GPR loop overwrites x5 afterward so state is preserved).
200	 198     if (state.flags & HYBRID_FLAG_V) {
201	 199       // V data regfile: reload v0..v31 from the shared scratch region via the
202	 200       // Program Buffer. Runs BEFORE the architectural V-CSR restore below
203	 201       // because the sweep's own vsetvl (e8/m8) clobbers vtype/vl/vstart, which
204	 202       // the restore then overwrites with the architectural values. The sweep
205	 203       // uses x5/x6/x7 as scratch (x7 is the group base pointer); the GPR loop
206	 204       // below restores all three. The scratch is vlenb-packed
207	 205       // (stage_v_to_scratch), so the sweep takes only the runtime vlenb.
208	 206       if (scratch_gpa_ == kVScratchGpaUnset)
209	 207         throw std::runtime_error(
210	 208           "ResumeDriver::resume: V state present but scratch GPA unset");
211	 209       // LG2: elide the reload sweep when every v-reg already holds the
212	 210       // engine's reset bytes.
213	 211       const bool v_data_equal = has_baseline_
214	 212         && std::memcmp(state.vreg, baseline_.vreg, sizeof state.vreg) == 0;
215	 213       if (v_data_equal)
216	 214         baseline_skip_count_ += 32;
217	 215       else
218	 216         pb_v_data_sweep(bus_, scratch_gpa_, state.vlenb, /*load=*/true);
219	 217 
220	 218       // Tier-B: vtype+vl via vsetvl x0,x5,x6 in PB.
221	 219       // Direct csrrw to vtype sets vill; vl is read-only. Stage operands in
222	 220       // scratch GPRs x5(vl) and x6(vtype) then let vsetvl set both atomically.
223	 221       // x5/x6 are overwritten by the GPR loop below, so no leakage.
224	 222       // LG2 clobber rule: the data sweep's own vsetvl overwrote vtype/vl/
225	 223       // vstart, so baseline equality only proves this vsetvl redundant when
226	 224       // the sweep did NOT run.
227	 225       const bool vcfg_equal = v_data_equal && v_cfg_at_reset_
228	 226         && state.vl == baseline_.vl && state.vtype == baseline_.vtype;
229	 227       if (vcfg_equal) {
230	 228         ++baseline_skip_count_;  // the elided vsetvl exec
231	 229       } else {
232	 230         write_64bit_register(regno_gpr(5), state.vl);
233	 231         write_64bit_register(regno_gpr(6), state.vtype);
234	 232         const std::array<uint32_t, 1> pb_vsetvl = { encode_vsetvl(0, 5, 6) };
235	 233         exec_progbuf(bus_, std::span<const uint32_t>{pb_vsetvl});
236	 234       }
237	 235       // vstart must come AFTER vsetvl: vsetvl resets vstart to 0 -- so its
238	 236       // baseline skip is likewise only valid when no vsetvl executed.
239	 237       if (!(vcfg_equal && baseline_skips(state.vstart, baseline_.vstart)))
240	 238         write_csr_abstract_or_pb(kCsrVstart, state.vstart);
241	 239       if (!baseline_skips(state.vxsat, baseline_.vxsat))
242	 240         write_csr_abstract_or_pb(kCsrVxsat,  state.vxsat);
243	 241       if (!baseline_skips(state.vxrm, baseline_.vxrm))
244	 242         write_csr_abstract_or_pb(kCsrVxrm,   state.vxrm);
245	 243       if (!baseline_skips(state.vcsr, baseline_.vcsr))
246	 244         write_csr_abstract_or_pb(kCsrVcsr,   state.vcsr);
247	 245     }
248	 246 
249	 247     // L6: dret resumes into dcsr.prv, which is M after the boot halt. For an
250	 248     // S/U-mode handoff, read-modify-write the prv field so the ROI executes
251	 249     // in the drained privilege; M-mode states skip the write (prv already 3).
252	 250     // Before the GPR loop: a PB fallback would clobber scratch x5.
253	 251     if (state.priv != 3) {
254	 252       // L2 slice: with PMP implemented and no matching entry, every S/U
255	 253       // access faults (priv spec v1.10) -- mirror the producer's PMP block
256	 254       // so the ROI can fetch at all. All pmpaddr before any pmpcfg (a locked
257	 255       // cfg discards later addr writes); odd pmpcfg CSRs do not exist on
258	 256       // RV64. Tolerant writes: entries beyond what the hart implements
259	 257       // mirror as no-ops. M-mode handoffs keep PMP pass-through-only (L2).
260	 258       for (uint16_t i = 0; i < HYBRID_PMP_ADDR_NUM; ++i)
261	 259         write_csr_tolerant(kCsrPmpaddr0 + i, state.pmpaddr[i]);
262	 260       for (uint16_t i = 0; i < HYBRID_PMP_CFG_NUM; i += 2)
263	 261         write_csr_tolerant(kCsrPmpcfg0 + i, state.pmpcfg[i]);
264	 262 
265	 263       const uint64_t dcsr =
266	 264         read_register_64(bus_, regno_csr(kCsrDcsr), "ResumeDriver dcsr");
267	 265       write_csr_abstract_or_pb(kCsrDcsr,
268	 266                                (dcsr & ~uint64_t{0x3}) | state.priv);
269	 267       // An M-only core WARL-pins dcsr.prv to 3; resuming anyway would
270	 268       // silently measure the ROI in the wrong privilege. Verify and abort.
271	 269       const uint64_t got =
272	 270         read_register_64(bus_, regno_csr(kCsrDcsr), "ResumeDriver dcsr verify")
273	 271         & 0x3u;
274	 272       if (got != state.priv)
275	 273         throw std::runtime_error(
276	 274           "ResumeDriver::resume: engine does not implement privilege level "
277	 275           + std::to_string(state.priv)
278	 276           + " (dcsr.prv pinned to " + std::to_string(got)
279	 277           + "); pick an S/U-capable engine");
280	 278     }
281	 279 
282	 280     // Andes V5 + M-ext CSR restore (abstract-only, LG1-gated). See
283	 281     // restore_andes_m_ext.
284	 282     restore_andes_m_ext(state);
285	 283 
286	 284     // v5: L2C MMIO config restore. Runs BEFORE the GPR loop (like the V sweep):
287	 285     // it stages an address + value into scratch GPRs x5/x6 and the GPR loop
288	 286     // below overwrites them with their architectural values, so the clobber is
289	 287     // safe. It CANNOT run after the loop, where every GPR already holds its
290	 288     // final value. See restore_l2c.
291	 289     restore_l2c(state);
292	 290 
293	 291     // GPRs + DPC (after V CSRs so PB scratch x5 is safe to overwrite): one
294	 292     // abstract register write per GPR.
295	 293     for (uint16_t i = 1; i < 32; ++i)
296	 294       write_64bit_register(regno_gpr(i), state.gpr[i]);
297	 295     write_64bit_register(regno_csr(kCsrDpc), state.pc);
298	 296 
299	 297     write_csr_tolerant_gated(kCsrMtvec, state.mtvec, baseline_.mtvec);
300	 298 
301	 299     // L23: mscratch is the M-mode software scratch CSR -- a pure read/write
302	 300     // register with no hardware side effects, legal to use inside a trap-free
303	 301     // ROI. Restore it so a value stashed before the handoff survives into the
304	 302     // vsim phase.
305	 303     write_csr_tolerant_gated(kCsrMscratch, state.mscratch, baseline_.mscratch);
306	 304 
307	 305     // L24: the writable M-mode trap/interrupt CSRs. In the trap-free,
308	 306     // interrupt-free ROI envelope these are ordinary read/write registers, so a
309	 307     // value stashed before the handoff must survive into the vsim phase (same
310	 308     // round-trip as mscratch). Tolerant writes: a WARL / read-only field (mip's
311	 309     // hardware-driven pending bits, or mtval on a core that hardwires it)
312	 310     // mirrors as a no-op. medeleg/mideleg/satp stay unrestored -- they are
313	 311     // S-mode CSRs the M-only default engine does not implement (L3/L4).
314	 312     write_csr_tolerant_gated(kCsrMepc,   state.mepc,   baseline_.mepc);
315	 313     write_csr_tolerant_gated(kCsrMcause, state.mcause, baseline_.mcause);
316	 314     write_csr_tolerant_gated(kCsrMtval,  state.mtval,  baseline_.mtval);
317	 315     write_csr_tolerant_gated(kCsrMie,    state.mie,    baseline_.mie);
318	 316     write_csr_tolerant_gated(kCsrMip,    state.mip,    baseline_.mip);
319	 317 
320	 318     // Andes cache fix: restore the machine setup CSRs crt0 wrote at boot. The
321	 319     // functional engine ran crt0 (where `csrw mcache_ctl` enables the L1 I/D
322	 320     // caches) but has no cache model, so without this the cycle engine resumes
323	 321     // at the ROI with caches at their reset default -- DISABLED -- and the
324	 322     // whole measured window runs uncached, inflating it severalfold. Tolerant
325	 323     // writes: an engine without these custom CSRs (e.g. non-Andes) mirrors the
326	 324     // write as a no-op, and a drained 0 (caches were off) restores the reset
327	 325     // state, so this is always safe to issue.
328	 326     if (wm_live(state, HYBRID_WM_MCACHE_CTL))
329	 327       write_csr_tolerant_gated(kCsrMcacheCtl, state.mcache_ctl,
330	 328                                baseline_.mcache_ctl);
331	 329     if (wm_live(state, HYBRID_WM_MMISC_CTL))
332	 330       write_csr_tolerant_gated(kCsrMmiscCtl,  state.mmisc_ctl,
333	 331                                baseline_.mmisc_ctl);
334	 332 
335	 333     // F-T2.4: restore mcycle/minstret so the vsim phase continues counting
336	 334     // from QEMU1's drain value. Without this, vsim's local counter starts
337	 335     // at zero, so the drained mcycle delta (vsim minus QEMU 1) would no
338	 336     // longer measure the ROI. PB fallback uses x5 as scratch; safe to
339	 337     // overwrite here as the GPR loop already ran.
340	 338     write_csr_abstract_or_pb(kCsrMcycle,   state.mcycle);
341	 339     write_csr_abstract_or_pb(kCsrMinstret, state.minstret);
342	 340 
343	 341     clear_cmderr_if_set();
344	 342     request_resume();
345	 343     poll_until_set(bus_, kDmstatus, kDmstatusAllresumeack,
346	 344                    "ResumeDriver resume");
347	 345   }
