349	 347 private:
350	 348   void request_halt()
351	 349   {
352	 350     bus_.write(kDmcontrol, kDmcontrolDmactive | kDmcontrolHaltreq);
353	 351   }
354	 352 
355	 353   void request_resume()
356	 354   {
357	 355     bus_.write(kDmcontrol, kDmcontrolDmactive | kDmcontrolResumereq);
358	 356   }
359	 357 
360	 358   void write_64bit_register(uint16_t regno, uint64_t value)
361	 359   {
362	 360     write_register_abstract(bus_, regno, value);
363	 361   }
364	 362 
365	 363   // v5: write back the WRITABLE boot-static L2C config registers via
366	 364   // Program-Buffer word stores. The L2C block is MMIO, not a CSR, so each write
367	 365   // is `sw x5, 0(x6)` with the register address staged in x6 and the value (low
368	 366   // word) in x5. Restores ONLY the config registers the ROI can hold as plain
369	 367   // state: Control (CEN/prefetch/ECC/RAM timing), HPM Control, Way Allocation
370	 368   // Masks. The read-only Configuration Register, the side-effecting CCTL command
371	 369   // registers (writing one re-issues an L2 cache op), and the write-1-clear
372	 370   // error registers are captured in the record but NEVER written back.
373	 371   //
374	 372   // Hard-gated on the engine having an L2C (l2c_present_): a store to an absent
375	 373   // L2C region faults the Program Buffer, so unlike a tolerant CSR write this
376	 374   // must issue nothing on a core without an L2C. x5/x6 are safe scratch here --
377	 375   // the caller runs this before the GPR loop, which overwrites both.
378	 376   void restore_l2c(const hybrid_state_v1& state)
379	 377   {
380	 378     if (!(state.flags & HYBRID_FLAG_L2C)) return;
381	 379     if (!l2c_present_) return;
382	 380 
383	 381     pb_store_l2c_reg(HYBRID_L2C_OFF_CONTROL,
384	 382                      state.l2c.reg[HYBRID_L2C_OFF_CONTROL / 8]);
385	 383     pb_store_l2c_reg(HYBRID_L2C_OFF_HPM_CTL0,
386	 384                      state.l2c.reg[HYBRID_L2C_OFF_HPM_CTL0 / 8]);
387	 385     for (uint32_t i = 0; i < HYBRID_L2C_WAYMASK_NUM; ++i) {
388	 386       const uint32_t off = HYBRID_L2C_OFF_WAYMASK0 + i * 8u;
389	 387       pb_store_l2c_reg(off, state.l2c.reg[off / 8]);
390	 388     }
391	 389   }
392	 390 
393	 391   // One L2C register store: stage the MMIO address in x6 and the value's low
394	 392   // word in x5, then execute `sw x5, 0(x6)` in the Program Buffer. Word store
395	 393   // per DS220 11.8.3 (single transfer, access size < 8 bytes); all documented
396	 394   // L2C control bits live in the low 32.
397	 395   void pb_store_l2c_reg(uint32_t offset, uint64_t value)
398	 396   {
399	 397     write_register_abstract(bus_, regno_gpr(6), l2c_base_ + offset);
400	 398     write_register_abstract(bus_, regno_gpr(5), value & 0xffffffffu);
401	 399     const std::array<uint32_t, 1> pb = { encode_sw(5, 6, 0) };
402	 400     exec_progbuf(bus_, std::span<const uint32_t>{pb});
403	 401   }
404	 402 
405	 403   // Andes V5 + M-ext CSR restore: one caps-gated abstract write per CSR
406	 404   // (pmaaddr before pmacfg, mirroring the PMP restore ordering), each gated by
407	 405   // the LG1 reset baseline. Abstract-only by design -- a batched Program-Buffer
408	 406   // sweep can't tolerate a cmderr on one CSR without corrupting the rest of the
409	 407   // batch (a WARL/read-only CSR faults the whole group mid-sweep), whereas the
410	 408   // per-CSR abstract path tolerates a single failure and moves on.
411	 409   void restore_andes_m_ext(const hybrid_state_v1& state)
412	 410   {
413	 411     const bool andes = state.flags & HYBRID_FLAG_ANDES;
414	 412     const bool mext  = state.flags & HYBRID_FLAG_M_EXT;
415	 413     if (!andes && !mext) return;
416	 414 
417	 415     // Each write is double-gated: caps (the ENGINE implements the CSR) and the
418	 416     // v6 write-mask (the PRODUCER's guest actually wrote it -- wm_live).
419	 417     if (andes) {
420	 418 #define X(field, addr, name)                                                  \
421	 419   if (caps_.supports_csr(addr)                                                \
422	 420       && wm_live(state, HYBRID_WM_ANDES_BASE + HYBRID_WM_ANDES_IDX_##field))  \
423	 421     write_csr_tolerant_gated(addr, state.andes.field, baseline_.andes.field);
424	 422       HYBRID_ANDES_CSR_LIST(X)
425	 423 #undef X
426	 424       for (uint16_t i = 0; i < HYBRID_PMA_ADDR_NUM; ++i)
427	 425         if (caps_.supports_csr(HYBRID_PMA_ADDR0_CSR + i)
428	 426             && wm_live(state, HYBRID_WM_PMAADDR_BASE + i))
429	 427           write_csr_tolerant_gated(HYBRID_PMA_ADDR0_CSR + i,
430	 428                                    state.andes.pmaaddr[i],
431	 429                                    baseline_.andes.pmaaddr[i]);
432	 430       for (uint16_t i = 0; i < HYBRID_PMA_CFG_NUM; ++i)
433	 431         if (caps_.supports_csr(HYBRID_PMA_CFG0_CSR + 2 * i)
434	 432             && wm_live(state, HYBRID_WM_PMACFG_BASE + i))
435	 433           write_csr_tolerant_gated(HYBRID_PMA_CFG0_CSR + 2 * i,
436	 434                                    state.andes.pmacfg[i],
437	 435                                    baseline_.andes.pmacfg[i]);
438	 436     }
439	 437     if (mext) {
440	 438 #define X(field, addr, name)                                                  \
441	 439   if (caps_.supports_csr(addr)                                                \
442	 440       && wm_live(state, HYBRID_WM_M_EXT_BASE + HYBRID_WM_M_EXT_IDX_##field))  \
443	 441     write_csr_tolerant_gated(addr, state.m_ext.field, baseline_.m_ext.field);
444	 442       HYBRID_M_EXT_CSR_LIST(X)
445	 443 #undef X
446	 444     }
447	 445   }
448	 446 
449	 447   // Abstract-first CSR write with Program Buffer fallback.
450	 448   // Tries an abstract register write; if the DM signals cmderr, clears it,
451	 449   // stages the value in scratch_gpr via abstract GPR write, then executes a
452	 450   // one-instruction PB (`csrrw x0, csr, scratch_gpr`).  scratch_gpr defaults
453	 451   // to x5 (t0) which the GPR restore loop overwrites later.
454	 452   void write_csr_abstract_or_pb(uint16_t csr, uint64_t value,
455	 453                                  uint8_t scratch_gpr = 5)
456	 454   {
457	 455     write_64bit_register(regno_csr(csr), value);
458	 456     if ((bus_.read(kAbstractcs) & kAbstractcsCmderrMask) == 0u) return;
459	 457     bus_.write(kAbstractcs, kAbstractcsCmderrMask);  // W1C: clear sticky error
460	 458     write_64bit_register(regno_gpr(scratch_gpr), value);
461	 459     const std::array<uint32_t, 1> pb = { encode_csrrw(0, csr, scratch_gpr) };
462	 460     exec_progbuf(bus_, std::span<const uint32_t>{pb});
463	 461   }
464	 462 
465	 463   // Write a CSR-addressable register and clear any cmderr the DM raised.
466	 464   // Used for CSRs whose abstract-access support may be implementation
467	 465   // dependent; a missing CSR mirrors as a no-op rather than blocking the
468	 466   // remaining writes.
469	 467   void write_csr_tolerant(uint16_t csr, uint64_t value)
470	 468   {
471	 469     write_64bit_register(regno_csr(csr), value);
472	 470     clear_cmderr_if_set();
473	 471   }
474	 472 
475	 473   // v6: true when the handoff says this mask-governed CSR is live -- the
476	 474   // producer's guest actually wrote it, or the producer carried no mask at all
477	 475   // (pre-v6 file: restore-everything fallback). An untouched CSR is skipped so
478	 476   // the engine keeps its OWN reset value: the drained value is only the
479	 477   // producer's reset default, which may legitimately differ from this RTL's
480	 478   // (msp_bound all-ones vs 0, milmb.IEN 0 vs 1; see hybrid/write_mask.h).
481	 479   static auto wm_live(const hybrid_state_v1& state, int slot) -> bool
482	 480   {
483	 481     if (!(state.flags & HYBRID_FLAG_WRITE_MASK)) return true;
484	 482     return hybrid_wm_test(state.write_mask, static_cast<unsigned>(slot)) != 0;
485	 483   }
486	 484 
487	 485   // LG1: true (and counted) when the reset baseline marks this write a no-op.
488	 486   auto baseline_skips(uint64_t value, uint64_t reset_value) -> bool
489	 487   {
490	 488     if (!has_baseline_ || value != reset_value) return false;
491	 489     ++baseline_skip_count_;
492	 490     return true;
493	 491   }
494	 492 
495	 493   // Tolerant CSR write elided when the value already equals the engine's
496	 494   // reset value (reset_value is only meaningful when the baseline is set;
497	 495   // baseline_ is zero-initialized otherwise and baseline_skips ignores it).
498	 496   void write_csr_tolerant_gated(uint16_t csr, uint64_t value,
499	 497                                 uint64_t reset_value)
500	 498   {
501	 499     if (baseline_skips(value, reset_value)) return;
502	 500     write_csr_tolerant(csr, value);
503	 501   }
504	 502 
505	 503   // abstractcs.cmderr is sticky per the Debug Spec - a subsequent command
506	 504   // is rejected until the bits are W1C-cleared. We tolerate per-register
507	 505   // failures (e.g. unimplemented FPR/CSR Abstract access) by clearing the
508	 506   // error before resuming so the hart isn't left in a stuck state.
509	 507   // B17: record the last observed non-zero cmderr and a clear count so a
510	 508   // partially-broken restore is observable via the public accessors
511	 509   // instead of silently swallowed.
512	 510   void clear_cmderr_if_set()
513	 511   {
514	 512     const auto status = bus_.read(kAbstractcs);
515	 513     const auto code = (status & kAbstractcsCmderrMask) >> 8;
516	 514     if (code != 0u) {
517	 515       last_observed_cmderr_ = code;
518	 516       ++cmderr_clear_count_;
519	 517       bus_.write(kAbstractcs, kAbstractcsCmderrMask);
520	 518     }
521	 519   }
522	 520 
523	 521   DmiBus& bus_;
524	 522   uint64_t scratch_gpa_ = kVScratchGpaUnset;  // L26: V transport page GPA
525	 523   AndesCaps caps_ = AndesCaps::all();         // target core's Andes-CSR support
526	 524   bool l2c_present_ = false;                  // v5: engine has an L2C (set_l2c)
527	 525   uint64_t l2c_base_ = 0;                     // v5: L2C MMIO register base
528	 526   hybrid_state_v1 baseline_{};                // LG1: engine reset-state drain
529	 527   bool has_baseline_ = false;                 // baseline_ valid only when set
530	 528   bool v_cfg_at_reset_ = true;                // false: capture clobbered vcfg
531	 529   uint64_t baseline_skip_count_ = 0;          // LG1: elided tolerant writes
532	 530   uint32_t last_observed_cmderr_ = 0;
533	 531   uint64_t cmderr_clear_count_   = 0;
534	 532 
535	 533 public:
536	 534   // B17: diagnostic side channel. Non-zero last_observed_cmderr() means
537	 535   // at least one abstract write tripped a sticky cmderr the restore
538	 536   // tolerated by clearing. cmderr_clear_count() is the total number of
539	 537   // such clears across all calls into clear_cmderr_if_set() this run.
540	 538   auto last_observed_cmderr() const -> uint32_t { return last_observed_cmderr_; }
541	 539   auto cmderr_clear_count() const -> uint64_t   { return cmderr_clear_count_; }
542	 540 };
543	 541 
544	 542 // Read a 64-bit hart register (GPR / FPR / CSR by abstract regno) over DMI
545	 543 // via an Abstract Command. Halts-and-reads contract: caller must have the
546	 544 // hart in the halted state. Shared by StateDrain (drain at exit). If
547	 545 // abstractcs.cmderr goes sticky after the command, the helper clears it and
548	 546 // reports 0 rather than blocking the caller -- a missing CSR mirrors as zero
549	 547 // instead of corrupting the adjacent field.
550	 548 inline auto read_register_64_checked(DmiBus& bus, uint16_t regno,
551	 549                                      const char* poll_label
552	 550                                        = "read_register_64")
553	 551   -> std::optional<uint64_t>
554	 552 {
555	 553   using RD = ResumeDriver;
556	 554   bus.write(RD::kCommand,
557	 555             access_register_command(regno, AarSize::Bits64, /*write=*/false));
558	 556   poll_until_clear(bus, RD::kAbstractcs, RD::kAbstractcsBusy, poll_label);
559	 557   const auto status = bus.read(RD::kAbstractcs);
560	 558   if ((status & RD::kAbstractcsCmderrMask) != 0u) {
561	 559     bus.write(RD::kAbstractcs, RD::kAbstractcsCmderrMask);
562	 560     return std::nullopt;
563	 561   }
564	 562   const uint64_t lo = bus.read(RD::kData0);
565	 563   const uint64_t hi = bus.read(RD::kData1);
566	 564   return lo | (hi << 32);
567	 565 }
568	 566 
569	 567 inline auto read_register_64(DmiBus& bus, uint16_t regno,
570	 568                              const char* poll_label = "read_register_64")
571	 569   -> uint64_t
572	 570 {
573	 571   return read_register_64_checked(bus, regno, poll_label).value_or(0u);
574	 572 }
