37	// DMI register addresses from RISC-V Debug Spec 1.0.
38	constexpr uint8_t kDmcontrol  = 0x10;
39	constexpr uint8_t kDmstatus   = 0x11;
40	constexpr uint8_t kAbstractcs = 0x16;
41	constexpr uint8_t kCommand    = 0x17;
42	constexpr uint8_t kData0      = 0x04;
43	constexpr uint8_t kData1      = 0x05;
44	
45	// CSR numbers from Debug Spec.
46	constexpr uint16_t kCsrDpc = 0x7B1;
47	
48	struct DmiOp
49	{
50	  enum class Kind
51	  {
52	    Write,
53	    Read,
54	  };
55	  Kind kind;
56	  uint8_t reg;
57	  uint32_t value;  // for writes only
58	};
59	
60	struct RecordingBus final : hybrid::DmiBus
61	{
62	  std::vector<DmiOp> ops;
63	
64	  // bit 9: allhalted, bit 17: allresumeack. Answering both lets the poll
65	  // loops finish on their first read. abstractcs reads return 0 (busy clear,
66	  // no cmderr), so each abstract write completes immediately.
67	  uint32_t dmstatus_value = 0;
68	
69	  // When set, an abstract write-COMMAND to this CSR regno raises a sticky
70	  // cmderr (cleared only by the W1C abstractcs write the driver issues).
71	  // Models a hart that NACKs a particular abstract CSR access.
72	  std::optional<uint16_t> fail_csr_write;
73	
74	  void write(uint8_t reg, uint32_t value) override
75	  {
76	    ops.push_back({DmiOp::Kind::Write, reg, value});
77	    if (reg == kAbstractcs && (value & kCmderrMask) != 0u)
78	      cmderr_sticky_ = false;  // W1C clear
79	    if (reg == kCommand && fail_csr_write) {
80	      const auto regno    = static_cast<uint16_t>(value & 0xffffu);
81	      const bool is_write = ((value >> 16) & 1u) != 0u;
82	      if (is_write && regno == hybrid::regno_csr(*fail_csr_write))
83	        cmderr_sticky_ = true;
84	    }
85	  }
86	
87	  auto read(uint8_t reg) -> uint32_t override
88	  {
89	    ops.push_back({DmiOp::Kind::Read, reg, 0});
90	    if (reg == kDmstatus) return dmstatus_value;
91	    if (reg == kAbstractcs && cmderr_sticky_) return kCmderrMask;
92	    return 0;
93	  }
94	
95	private:
96	  static constexpr uint32_t kCmderrMask = 0x7u << 8;
97	  bool cmderr_sticky_ = false;
98	};
99	
100	auto rv64_state(uint64_t pc, uint64_t x1) -> hybrid_state_v1
101	{
102	  hybrid_state_v1 s{};
103	  s.magic = HYBRID_STATE_MAGIC;
104	  s.version = HYBRID_STATE_VERSION;
105	  s.flags = HYBRID_FLAG_RV64;
106	  s.pc = pc;
107	  s.priv = 3;
108	  s.gpr[1] = x1;
109	  return s;
110	}
111	
112	auto find_write(const std::vector<DmiOp>& ops, uint8_t reg)
113	  -> std::vector<uint32_t>
114	{
115	  std::vector<uint32_t> values;
116	  for (const auto& op : ops)
117	    if (op.kind == DmiOp::Kind::Write && op.reg == reg)
118	      values.push_back(op.value);
119	  return values;
120	}
121	
122	}  // namespace
