124	TEST_CASE("resume halts the hart before any abstract command")
125	{
126	  RecordingBus bus;
127	  bus.dmstatus_value = (1u << 9) | (1u << 17);
128	
129	  hybrid::ResumeDriver driver(bus);
130	  driver.resume(rv64_state(/*pc=*/0x80001000, /*x1=*/0xdeadbeef));
131	
132	  // The first write must prime dmactive (DM out of reset) BEFORE haltreq is
133	  // accepted; the second write must add haltreq while keeping dmactive set.
134	  REQUIRE(bus.ops.size() >= 2);
135	
136	  const auto& prime = bus.ops[0];
137	  CHECK(prime.kind == DmiOp::Kind::Write);
138	  CHECK(prime.reg == kDmcontrol);
139	  CHECK((prime.value & 1u) == 1u);                  // dmactive
140	  CHECK(((prime.value >> 31) & 1u) == 0u);          // haltreq NOT yet set
141	
142	  const auto& halt = bus.ops[1];
143	  CHECK(halt.kind == DmiOp::Kind::Write);
144	  CHECK(halt.reg == kDmcontrol);
145	  CHECK((halt.value & 1u) == 1u);                   // dmactive still set
146	  CHECK(((halt.value >> 31) & 1u) == 1u);           // haltreq
147	}
