150	{
151	  RecordingBus bus;
152	  bus.dmstatus_value = (1u << 9) | (1u << 17);
153	
154	  auto s = rv64_state(0x80001000, 0xdeadbeef);
155	  for (int i = 0; i < 32; ++i) s.gpr[i] = 0xa00000000ULL + i;
156	
157	  hybrid::ResumeDriver driver(bus);
158	  driver.resume(s);
159	
160	  std::vector<uint32_t> cmds;
161	  for (const auto& op : bus.ops)
162	    if (op.kind == DmiOp::Kind::Write && op.reg == kCommand)
163	      cmds.push_back(op.value);
164	
165	  CHECK(cmds.size() >= 31);
166	
167	  // The first 31 COMMAND writes program x1..x31 in order, one abstract write
168	  // per register (the value rides the DATA0/DATA1 written just before each).
169	  for (int i = 1; i < 32; ++i) {
170	    const auto expect =
171	      hybrid::access_register_command(hybrid::regno_gpr(i),
172	                                      hybrid::AarSize::Bits64, /*write=*/true);
173	    CHECK(cmds[i - 1] == expect);
174	  }
175	
176	  // x0 is never programmed.
177	  for (const auto& cmd : cmds) {
178	    const uint16_t regno = cmd & 0xffffu;
179	    CHECK(regno != hybrid::regno_gpr(0));
180	  }
181	}
