183	TEST_CASE("resume writes DPC = state.pc")
184	{
185	  RecordingBus bus;
186	  bus.dmstatus_value = (1u << 9) | (1u << 17);
187	
188	  constexpr uint64_t pc = 0x12345678'9ABCDEF0ULL;
189	  hybrid::ResumeDriver driver(bus);
190	  driver.resume(rv64_state(pc, 0));
191	
192	  // Look for the COMMAND write that targets CSR DPC (regno = 0x7B1).
193	  std::optional<std::size_t> dpc_cmd_idx;
194	  for (std::size_t i = 0; i < bus.ops.size(); ++i) {
195	    const auto& op = bus.ops[i];
196	    if (op.kind == DmiOp::Kind::Write && op.reg == kCommand
197	        && (op.value & 0xffffu) == kCsrDpc) {
198	      dpc_cmd_idx = i;
199	      break;
200	    }
201	  }
202	  REQUIRE(dpc_cmd_idx.has_value());
203	
204	  // Immediately preceding writes must set DATA0=low32(pc), DATA1=high32(pc).
205	  REQUIRE(*dpc_cmd_idx >= 2);
206	  const auto& d0 = bus.ops[*dpc_cmd_idx - 2];
207	  const auto& d1 = bus.ops[*dpc_cmd_idx - 1];
208	  CHECK(d0.reg == kData0);
209	  CHECK(d0.value == uint32_t(pc & 0xffffffffu));
210	  CHECK(d1.reg == kData1);
211	  CHECK(d1.value == uint32_t((pc >> 32) & 0xffffffffu));
212	}
