281	auto cmd_regnos(const std::vector<DmiOp>& ops) -> std::vector<uint16_t>
282	{
283	  std::vector<uint16_t> ns;
284	  for (const auto& op : ops)
285	    if (op.kind == DmiOp::Kind::Write && op.reg == kCommand)
286	      ns.push_back(static_cast<uint16_t>(op.value & 0xffffu));
287	  return ns;
288	}
