298	TEST_CASE("resume does NOT program M-mode CSRs/PMP via DM Abstract Commands; "
299	          "those fields are pass-through-merged at drain time instead")
300	{
301	  RecordingBus bus;
302	  bus.dmstatus_value = (1u << 9) | (1u << 17);
303	
304	  auto s = rv64_state(0x80001000, 0);
305	  s.mstatus = 0x1800ULL;
306	  for (int i = 0; i < HYBRID_PMP_CFG_NUM; ++i)  s.pmpcfg[i]  = 0xa0 + i;
307	  for (int i = 0; i < HYBRID_PMP_ADDR_NUM; ++i) s.pmpaddr[i] = 0xb0 + i;
308	
309	  hybrid::ResumeDriver driver(bus);
310	  driver.resume(s);
311	
312	  const auto ns = cmd_regnos(bus.ops);
313	  // mcycle(0xb00)/minstret(0xb02) are restored by resume (F-T2.4), mscratch
314	  // (0x340) since L23, and mepc(0x341)/mcause(0x342)/mtval(0x343)/mip(0x344)/
315	  // mie(0x304) since L24 -- none of those belong in this "must not program"
316	  // list. It now covers mstatus(0x300, restored only under FP/V; this state
317	  // has neither) plus the S-mode CSRs medeleg(0x302)/mideleg(0x303)/satp(0x180)
318	  // that the M-only default engine does not implement; those stay drain-time
319	  // pass-through.
320	  for (uint16_t csr : {0x300, 0x302, 0x303, 0x180})
321	    CHECK_FALSE(contains_regno(ns, hybrid::regno_csr(csr)));
322	  for (uint16_t i = 0; i < HYBRID_PMP_CFG_NUM; ++i)
323	    CHECK_FALSE(contains_regno(ns, hybrid::regno_csr(0x3a0 + i)));
324	}
