331	{
332	  for (std::size_t i = 0; i < ops.size(); ++i) {
333	    const auto& op = ops[i];
334	    if (op.kind == DmiOp::Kind::Write && op.reg == kCommand
335	        && (op.value & 0xffffu) == regno)
336	      return i;
337	  }
338	  return std::nullopt;
339	}
