695	
696	  bool saw_cmd = false;
697	  std::size_t reads_since_cmd = 0;
698	  bool all_cmds_had_abstractcs_poll = true;
699	  for (const auto& op : bus.ops) {
700	    if (op.kind == DmiOp::Kind::Write && op.reg == kCommand) {
701	      if (saw_cmd && reads_since_cmd == 0)
702	        all_cmds_had_abstractcs_poll = false;
703	      saw_cmd = true;
704	      reads_since_cmd = 0;
705	    } else if (saw_cmd && op.kind == DmiOp::Kind::Read
706	               && op.reg == kAbstractcs) {
707	      ++reads_since_cmd;
708	    }
709	  }
710	  CHECK(all_cmds_had_abstractcs_poll);
711	  // The final kCommand write must also be followed by an abstractcs read.
712	  CHECK(reads_since_cmd > 0u);
