40	struct DmiOp
41	{
42	  enum class Kind
43	  {
44	    Write,
45	    Read,
46	  };
47	  Kind kind;
48	  uint8_t reg;
49	  uint32_t value;  // for writes only
50	};
51	
52	struct RecordingBus final : hybrid::DmiBus
53	{
54	  std::vector<DmiOp> ops;
55	
56	  // Test-controlled response values for reads.
57	  uint32_t dmstatus_value = 0;       // bit 9: allhalted, bit 17: allresumeack
58	  uint32_t abstractcs_value = 0;     // fallback when queue is empty
59	  std::deque<uint32_t> abstractcs_queue; // queued reads drain first
60	
61	  // When set, an abstract write-COMMAND to this CSR regno raises a sticky
62	  // cmderr (cleared by the W1C abstractcs write the driver issues on its PB
63	  // fallback). Models real hardware and -- unlike positional queueing -- is
64	  // robust to however many unrelated abstract ops precede the targeted write.
65	  std::optional<uint16_t> fail_csr_write;
66	
67	  // One-shot: when true, the NEXT kExecProgbufCmd write raises sticky cmderr
68	  // (so exec_progbuf throws after its post-exec abstractcs poll). The flag
69	  // re-arms to false after firing - tests can flip it back on to fail a
70	  // later PB exec.
71	  bool fail_next_pb_exec = false;
72	
73	  // Mini register file: abstract write-COMMANDs latch the staged DATA0/DATA1
74	  // into regfile[regno]; abstract read-COMMANDs load it back so read-modify-
75	  // write-verify sequences observe their own writes. Regnos in warl_ignore
76	  // model WARL fields the hart pins (the write is recorded but discarded),
77	  // e.g. dcsr.prv on a core without S/U modes.
78	  std::unordered_map<uint16_t, uint64_t> regfile;
79	  std::set<uint16_t> warl_ignore;
80	
81	  void write(uint8_t reg, uint32_t value) override
82	  {
83	    ops.push_back({DmiOp::Kind::Write, reg, value});
84	    if (reg == kData0) staged_data0_ = value;
85	    if (reg == kData1) staged_data1_ = value;
86	    if (reg == kAbstractcs && (value & kCmderrMask) != 0u)
87	      cmderr_sticky_ = false;  // W1C clear
88	    if (reg == kCommand && fail_csr_write) {
89	      const auto regno    = static_cast<uint16_t>(value & 0xFFFFu);
90	      const bool is_write = ((value >> 16) & 1u) != 0u;
91	      if (is_write && regno == hybrid::regno_csr(*fail_csr_write))
92	        cmderr_sticky_ = true;
93	    }
94	    if (reg == kCommand && value != hybrid::kExecProgbufCmd) {
95	      const auto regno    = static_cast<uint16_t>(value & 0xFFFFu);
96	      const bool is_write = ((value >> 16) & 1u) != 0u;
97	      if (is_write) {
98	        if (!warl_ignore.count(regno))
99	          regfile[regno] = (uint64_t{staged_data1_} << 32) | staged_data0_;
100	      } else {
101	        const auto it = regfile.find(regno);
102	        const uint64_t v = (it == regfile.end()) ? 0u : it->second;
103	        pending_data0_ = static_cast<uint32_t>(v);
104	        pending_data1_ = static_cast<uint32_t>(v >> 32);
105	      }
106	    }
107	    if (reg == kCommand && value == hybrid::kExecProgbufCmd
108	        && fail_next_pb_exec) {
109	      cmderr_sticky_ = true;
110	      fail_next_pb_exec = false;
111	    }
112	  }
113	
114	  auto read(uint8_t reg) -> uint32_t override
115	  {
116	    ops.push_back({DmiOp::Kind::Read, reg, 0});
117	    if (reg == kDmstatus) return dmstatus_value;
118	    if (reg == kData0)   return pending_data0_;
119	    if (reg == kData1)   return pending_data1_;
120	    if (reg == kAbstractcs) {
121	      if (cmderr_sticky_) return kCmderrMask;
122	      if (!abstractcs_queue.empty()) {
123	        auto v = abstractcs_queue.front();
124	        abstractcs_queue.pop_front();
125	        return v;
126	      }
127	      return abstractcs_value;
128	    }
129	    return 0;
130	  }
131	
132	private:
133	  static constexpr uint32_t kCmderrMask = 0x7u << 8;
134	  bool cmderr_sticky_ = false;
135	  uint32_t staged_data0_  = 0;
136	  uint32_t staged_data1_  = 0;
137	  uint32_t pending_data0_ = 0;
138	  uint32_t pending_data1_ = 0;
139	};
