141	auto rv64_state(uint64_t pc, uint64_t x10) -> hybrid_state_v1
142	{
143	  hybrid_state_v1 s{};
144	  s.magic = HYBRID_STATE_MAGIC;
145	  s.version = HYBRID_STATE_VERSION;
146	  s.flags = HYBRID_FLAG_RV64;
147	  s.pc = pc;
148	  s.priv = 3;
149	  s.gpr[10] = x10;
150	  return s;
151	}
