153	auto find_write(const std::vector<DmiOp>& ops, uint8_t reg)
154	  -> std::vector<uint32_t>
155	{
156	  std::vector<uint32_t> values;
157	  for (const auto& op : ops)
158	    if (op.kind == DmiOp::Kind::Write && op.reg == reg)
159	      values.push_back(op.value);
160	  return values;
161	}
