163	auto count_writes_to(const std::vector<DmiOp>& ops, uint8_t reg) -> std::size_t
164	{
165	  std::size_t n = 0;
166	  for (const auto& op : ops)
167	    if (op.kind == DmiOp::Kind::Write && op.reg == reg) ++n;
168	  return n;
169	}
